insert into public.crm_email_templates (key, name, kind, subject, preheader, html_body, text_body, vars, active, sort, updated_by, updated_at, design, one_off, audience, category, lang, description, created_by, created_at) values ('st_thanks_serving', 'Thank you after a serving', 'transactional', 'Thank you for Sunday, {{first_name|friend}}', '[What the day made possible, in a line]', '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 22px;"><tr><td style="padding:0 0 4px;"><div style="margin:-6px 0 -22px;"><div style="text-align:right;line-height:0;font-size:0;"><img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/brand/doodle-heart-gold.png" width="62" height="68" alt="" style="display:inline-block;width:62px;height:68px;border:0;"></div></div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-weight:700;font-size:11px;line-height:14px;letter-spacing:2px;text-transform:uppercase;color:#6F64AB;padding:0 0 12px;">Thank you</div><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:500;font-size:44px;line-height:46px;text-transform:uppercase;letter-spacing:.5px;color:#103F39;">Thank you for</div><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:500;font-size:44px;line-height:46px;text-transform:uppercase;letter-spacing:.5px;color:#DCA527;">being <span style="white-space:nowrap;">ther<img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/brand/e-large-gold-600.png" width="108" height="31" alt="E" style="display:inline-block;width:108px;height:31px;vertical-align:baseline;margin:0 2px;border:0;"></span></div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:17px;line-height:27px;color:#1F201E;padding-top:16px;">[What the day made possible, in one sentence]</div></td></tr></table><p style="margin:0 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">Hi {{first_name|there}},</p><p style="margin:0 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">On Sunday we served [how many] plates, and every one of them started a conversation. That is what you made possible.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 22px;"><tr><td width="33%" valign="top" style="padding:0 5px 0 0px;"><img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/photos/web/2024-10-autumn-volunteers-plating.jpg?v=1" width="169" alt="Two volunteers plate food side by side" style="display:block;width:100%;max-width:169px;height:auto;border:0;border-radius:8px;"></td><td width="33%" valign="top" style="padding:0 5px 0 5px;"><img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/photos/web/2023-10-autumn-plate-served.jpg?v=1" width="169" alt="Volunteers in green vests serving food onto a plate held out across the table" style="display:block;width:100%;max-width:169px;height:auto;border:0;border-radius:8px;"></td><td width="33%" valign="top" style="padding:0 0px 0 5px;"><img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/photos/web/2023-10-autumn-crew-behind-the-table.jpg?v=1" width="169" alt="Six volunteers in green vests smile behind the serving table in a park" style="display:block;width:100%;max-width:169px;height:auto;border:0;border-radius:8px;"></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 22px;"><tr><td style="border-left:3px solid #6F64AB;padding:4px 0 4px 18px;"><p style="margin:0;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:18px;line-height:28px;color:#103F39;">[A moment from the day, in the words of someone who was there]</p><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-weight:700;font-size:12px;line-height:18px;letter-spacing:1px;text-transform:uppercase;color:#6F64AB;padding-top:8px;">[Who said it]</div></td></tr></table><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:600;font-size:26px;line-height:28px;text-transform:uppercase;letter-spacing:.5px;color:#103F39;padding:10px 0 0;">Next time</div><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 14px;"><tr><td style="width:40px;height:3px;background-color:#DCA527;font-size:0;line-height:0;">&nbsp;</td></tr></table><p style="margin:0 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">Our next serving is [the date]. Same crew, new stories.</p><table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:10px auto 24px;"><tr><td style="background-color:#DCA527;border-radius:6px;" align="center"><a style="display:inline-block;padding:15px 34px;font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:600;font-size:20px;line-height:22px;letter-spacing:1px;text-transform:uppercase;color:#103F39;text-decoration:none;" href="https://welfareavenue.com/volunteer/" target="_blank">Pick your next Sunday</a></td></tr></table><p style="margin:8px 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">Warmly,<br><strong style="color:#103F39;font-weight:700;">[Who signs it]</strong><br><span style="color:#6F64AB;">Welfare Avenue</span></p>', 'Thank you

