n is the next serving?","hint":"Sunday 19 October"}],"source":"starter"}'::jsonb, false, 'volunteers', 'volunteers_welcome', 'en', 'The day after a serving: what the volunteers made possible, a moment from the day, the next date.', 'starter', now()) on conflict (key) do update set name = excluded.name, kind = excluded.kind, subject = excluded.subject, preheader = excluded.preheader, html_body = excluded.html_body, text_body = excluded.text_body, vars = excluded.vars, sort = excluded.sort, design = excluded.design, audience = excluded.audience, category = excluded.category, description = excluded.description, updated_by = excluded.updated_by, updated_at = now() where public.crm_email_templates.created_by = 'starter';
