insert into public.crm_email_templates (key, name, kind, subject, preheader, html_body, text_body, vars, active, sort, updated_by, updated_at, design, one_off, audience, category, lang, description, created_by, created_at) values ('st_gift_thanks', 'Thank you for a gift', 'transactional', 'Thank you, {{first_name|friend}}', 'Your gift is already at work in our community.', '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 22px;"><tr><td style="padding:0 0 4px;"><div style="margin:-6px 0 -22px;"><div style="text-align:right;line-height:0;font-size:0;"><img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/brand/doodle-heart-gold.png" width="62" height="68" alt="" style="display:inline-block;width:62px;height:68px;border:0;"></div></div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-weight:700;font-size:11px;line-height:14px;letter-spacing:2px;text-transform:uppercase;color:#6F64AB;padding:0 0 12px;">Thank you</div><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:500;font-size:44px;line-height:46px;text-transform:uppercase;letter-spacing:.5px;color:#103F39;">Thank you.</div><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:500;font-size:44px;line-height:46px;text-transform:uppercase;letter-spacing:.5px;color:#DCA527;">Here is <span style="white-space:nowrap;">wher<img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/brand/e-large-gold-600.png" width="108" height="31" alt="E" style="display:inline-block;width:108px;height:31px;vertical-align:baseline;margin:0 2px;border:0;"></span> it goes</div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:17px;line-height:27px;color:#1F201E;padding-top:16px;">Your gift keeps meals on the table and our youth-powered teams in the community.</div></td></tr></table><p style="margin:0 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">Hi {{first_name|there}},</p><p style="margin:0 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">Your gift of <strong style="color:#103F39;font-weight:700;">{{amount|your gift}}</strong>{{gift_date_line}} is already at work. It puts meals on the table on Sunday, and it keeps our teams in the community, building the trust that connects people with the support they need.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 22px;"><tr><td style="padding:0;"><img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/photos/web/2023-10-autumn-plate-served.jpg?v=1" width="528" alt="Volunteers in green vests serving food onto a plate held out across the table" style="display:block;width:100%;max-width:528px;height:auto;border:0;border-radius:8px;"></td></tr></table><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:600;font-size:26px;line-height:28px;text-transform:uppercase;letter-spacing:.5px;color:#103F39;padding:10px 0 0;">What a gift can do</div><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 14px;"><tr><td style="width:40px;height:3px;background-color:#DCA527;font-size:0;line-height:0;">&nbsp;</td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;"><tr><td style="padding:3px 12px 3px 0;vertical-align:top;width:10px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 0;"><tr><td style="width:10px;height:10px;border-radius:5px;background-color:#DCA527;font-size:0;line-height:0;">&nbsp;</td></tr></table></td><td style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:15px;line-height:24px;color:#1F201E;padding:3px 0;"><strong style="color:#103F39;font-weight:700;">$25</strong> covers one recipe from our cookbook, like a fruit salad for 8 to 10 people.</td></tr><tr><td style="padding:3px 12px 3px 0;vertical-align:top;width:10px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 0;"><tr><td style="width:10px;height:10px;border-radius:5px;background-color:#6F64AB;font-size:0;line-height:0;">&nbsp;</td></tr></table></td><td style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:15px;line-height:24px;color:#1F201E;padding:3px 0;"><strong style="color:#103F39;font-weight:700;">$75</strong> covers one volunteer cook’s batch: a dish for 30 to 35 people.</td></tr><tr><td style="padding:3px 12px 3px 0;vertical-align:top;width:10px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 0;"><tr><td style="width:10px;height:10px;border-radius:5px;background-color:#103F39;font-size:0;line-height:0;">&nbsp;</td></tr></table></td><td style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:15px;line-height:24px;color:#1F201E;padding:3px 0;"><strong style="color:#103F39;font-weight:700;">$250</strong> covers the groceries for a whole Sunday serving, about 50 plates.</td></tr><tr><td style="padding:3px 12px 3px 0;vertical-align:top;width:10px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 0;"><tr><td style="width:10px;height:10px;border-radius:5px;background-color:#DCA527;font-size:0;line-height:0;">&nbsp;</td></tr></table></td><td style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:15px;line-height:24px;color:#1F201E;padding:3px 0;"><strong style="color:#103F39;font-weight:700;">$20 a month</strong> adds up to about 100 portions over a year.</td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 24px;border-collapse:separate;"><tr><td style="background-color:#103F39;border-radius:8px;padding:24px 14px 22px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td colspan="3" align="center" style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-weight:700;font-size:11px;line-height:14px;letter-spacing:2px;text-transform:uppercase;color:#DCA527;padding:0 0 14px;">Since April 2020</td></tr><tr><td width="33%" align="center" valign="top" style="padding:0 6px;"><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:600;font-size:40px;line-height:42px;color:#DCA527;">14,000+</div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:13px;line-height:18px;color:#FFFAF2;padding-top:6px;">meals served</div></td><td width="33%" align="center" valign="top" style="padding:0 6px;"><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:600;font-size:40px;line-height:42px;color:#DCA527;">250+</div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:13px;line-height:18px;color:#FFFAF2;padding-top:6px;">servings</div></td><td width="33%" align="center" valign="top" style="padding:0 6px;"><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:600;font-size:40px;line-height:42px;color:#DCA527;">600+</div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:13px;line-height:18px;color:#FFFAF2;padding-top:6px;">volunteers</div></td></tr><tr><td colspan="3" align="center" style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:11px;line-height:16px;color:#FFFAF2;padding:14px 6px 0;opacity:.85;">Our best estimates from our records, rounded down.</td></tr></table></td></tr></table><p style="margin:0 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">Eligible gifts get an official tax receipt from us. Questions about your gift? Reply to this email.</p><p style="margin:8px 0 16px;font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:16px;line-height:26px;color:#1F201E;">With gratitude,<br><strong style="color:#103F39;font-weight:700;">The Welfare Avenue team</strong></p>', 'Thank you

THANK YOU. HERE IS WHERE IT GOES

Your gift keeps meals on the table and our youth-powered teams in the community.

Hi {{first_name|there}},

Your gift of {{amount|your gift}}{{gift_date_line}} is already at work. It puts meals on the table on Sunday, and it keeps our teams in the community, building the trust that connects people with the support they need.

WHAT A GIFT CAN DO

- $25 covers one recipe from our cookbook, like a fruit salad for 8 to 10 people.
- $75 covers one volunteer cook’s batch: a dish for 30 to 35 people.
- $250 covers the groceries for a whole Sunday serving, about 50 plates.
- $20 a month adds up to about 100 portions over a year.

Since April 2020
14,000+ meals served
250+ servings
600+ volunteers
Our best estimates from our records, rounded down.

Eligible gifts get an official tax receipt from us. Questions about your gift? Reply to this email.

With gratitude,
The Welfare Avenue team', '["first_name","amount","gift_date_line"]'::jsonb, true, 220, 'starter', now(), '{"v":1,"blocks":[{"id":"bgiftth0","type":"hero","style":"cream","kicker":"Thank you","lines":["Thank you.","Here is where it goes"],"lead":"Your gift keeps meals on the table and our youth-powered teams in the community.","doodle":"heart","accent":"gold","moveE":true},{"id":"bgiftth1","type":"text","text":"Hi {{first_name|there}},\n\nYour gift of **{{amount|your gift}}**{{gift_date_line}} is already at work. It puts meals on the table on Sunday, and it keeps our teams in the community, building the trust that connects people with the support they need."},{"id":"bgiftth2","type":"photo","src":"https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/photos/web/2023-10-autumn-plate-served.jpg?v=1","alt":"Volunteers in green vests serving food onto a plate held out across the table","caption":"","link":"","lib":"photo:57"},{"id":"bgiftth3","type":"heading","text":"What a gift can do"},{"id":"bgiftth4","type":"list","items":[{"lead":"$25","text":"covers one recipe from our cookbook, like a fruit salad for 8 to 10 people."},{"lead":"$75","text":"covers one volunteer cook’s batch: a dish for 30 to 35 people."},{"lead":"$250","text":"covers the groceries for a whole Sunday serving, about 50 plates."},{"lead":"$20 a month","text":"adds up to about 100 portions over a year."}]},{"id":"bgiftth5","type":"stats","style":"green","title":"Since April 2020","items":[{"n":"14,000+","label":"meals served"},{"n":"250+","label":"servings"},{"n":"600+","label":"volunteers"}],"note":"Our best estimates from our records, rounded down."},{"id":"bgiftth6","type":"text","text":"Eligible gifts get an official tax receipt from us. Questions about your gift? Reply to this email."},{"id":"bgiftth7","type":"signoff","closing":"With gratitude,","name":"The Welfare Avenue team","role":"","ps":""}],"source":"starter"}'::jsonb, false, 'donors', 'donors_thanks', 'en', 'Ri