insert into public.crm_email_templates (key, name, kind, subject, preheader, html_body, text_body, vars, active, sort, updated_by, updated_at, design, one_off, audience, category, lang, description, created_by, created_at) values ('st_appeal', 'Appeal', 'fundraising', '[The ask in a few words]', '[Why now, in a line]', '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 24px;border-collapse:separate;"><tr><td style="background-color:#103F39;border-radius:8px;padding:26px 28px 28px;"><div style="margin:-6px 0 -22px;"><div style="text-align:right;line-height:0;font-size:0;"><img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/brand/doodle-star-gold.png" width="62" height="66" alt="" style="display:inline-block;width:62px;height:66px;border:0;"></div></div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-weight:700;font-size:11px;line-height:14px;letter-spacing:2px;text-transform:uppercase;color:#DCA527;padding:0 0 12px;">[The campaign]</div><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:500;font-size:44px;line-height:46px;text-transform:uppercase;letter-spacing:.5px;color:#FFFAF2;">Help us</div><div style="font-family:''Barlow Condensed'',''Arial Narrow'',''Helvetica Neue'',Arial,sans-serif;font-weight:500;font-size:44px;line-height:46px;text-transform:uppercase;letter-spacing:.5px;color:#DCA527;">serve <span style="white-space:nowrap;">mor<img src="https://zwnmulmnvopclzcvytce.supabase.co/storage/v1/object/public/content-images/brand/e-large-gold-600.png" width="108" height="31" alt="E" style="display:inline-block;width:108px;height:31px;vertical-align:baseline;margin:0 2px;border:0;"></span></div><div style="font-family:''Space Grotesk'',''Helvetica Neue'',Arial,sans-serif;font-size:17px;line-height:27px;color:#FFFAF2;padding-top:16px;">[The goal in one sentence: how much, for what, b